const cranePhotoMarkup=(item,equipment,record='',preview=false)=>item.reference_photo_id?`<div class="reference-photo-block"><strong>${txt('referencePhoto')}</strong><button type="button" class="reference-photo-button" data-crane-photo="${esc(item.reference_photo_id)}" data-crane-equipment="${esc(equipment)}" data-crane-record="${esc(record)}" data-crane-preview="${preview?'1':''}"><span>${txt('loading')}</span></button></div>`:'';
function bindCranePhotos(root){root.querySelectorAll('[data-crane-photo]').forEach(el=>{
 const fetchPhoto=async()=>{const r=await api({action:'crane_photo_get',photo_id:el.dataset.cranePhoto,equipment_id:el.dataset.craneEquipment,crane_record_id:el.dataset.craneRecord||undefined,preview:el.dataset.cranePreview==='1'});return r.photo.url;};
 const load=async()=>{try{const url=await fetchPhoto();if(!el.isConnected)return;el.innerHTML=`<img loading="lazy" src="${esc(url)}" alt="${esc(t('referencePhoto'))}"><span>${txt('enlargePhoto')}</span>`;el.querySelector('img').onerror=()=>{el.textContent=t('photoLoadError');el.onclick=load;};el.onclick=async()=>{try{const fresh=await fetchPhoto();if(!el.isConnected)return;const modal=dialog('cranePhotoViewer',t('referencePhoto'),`<img class="reference-photo-large" src="${esc(fresh)}" alt="${esc(t('referencePhoto'))}">`);modal.style.zIndex='25';}catch{toast('error');}};}catch{if(el.isConnected){el.textContent=t('photoLoadError');el.onclick=load;}}};load();
});}
(()=>{
const labels={
 craneMonthlyManage:['QR18-05 固定式起重機每月定期檢查表（項目與照片設定）','QR18-05 Monthly crane inspection (items and photos)','QR18-05 Inspección mensual de grúa (ítems y fotos)','QR18-05 Kiểm tra cầu trục hằng tháng (mục và ảnh)'],
 craneTemplateHelp:['選擇部門與天車機號，修改或新增檢查項目及示範照片。現場人員開啟月檢表即可查看照片。已填寫月份保留原項目與照片，新紀錄使用新版設定。','Select a department and crane to edit or add items and reference photos. Operators can view photos in the monthly form. Existing records retain their original items and photos; new records use the updated template.','Seleccione departamento y grúa para editar o añadir ítems y fotos de referencia. Se ven en el formulario mensual. Los registros existentes conservan sus ítems y fotos; los nuevos usan la plantilla actualizada.','Chọn bộ phận và cầu trục để sửa hoặc thêm mục và ảnh hướng dẫn. Người kiểm tra xem ảnh trong mẫu tháng. Bản ghi cũ giữ mục và ảnh gốc; bản ghi mới dùng mẫu cập nhật.'],
 craneTemplateEdit:['修改項目與照片','Edit items and photos','Editar ítems y fotos','Sửa mục và ảnh'],
 craneTemplateAdd:['新增檢查項目','Add inspection item','Añadir ítem de inspección','Thêm mục kiểm tra'],
 craneTemplateSave:['儲存項目與照片','Save items and photos','Guardar ítems y fotos','Lưu mục và ảnh'],
 craneTemplateRequired:['請填寫每項的中文名稱與檢查基準，並等待照片上傳完成。','Enter a Chinese name and standard for each item and wait for uploads.','Introduzca nombre y criterio en chino para cada ítem y espere las cargas.','Nhập tên và tiêu chuẩn tiếng Trung cho từng mục và chờ tải ảnh xong.'],
 craneTemplateChanged:['項目設定已更新，請重新開啟表單。','The template changed. Reopen the form.','La plantilla cambió. Vuelva a abrir el formulario.','Mẫu đã đổi. Vui lòng mở lại biểu mẫu.'],
 craneTemplatePhotoHelp:['可上傳 JPG、PNG、WebP（原圖上限 10 MB），點照片可放大；移除照片不影響歷史紀錄。','Upload JPG, PNG or WebP (up to 10 MB). Click to enlarge. Removing a photo does not alter historical records.','Suba JPG, PNG o WebP (hasta 10 MB). Pulse para ampliar. Quitar una foto no altera registros históricos.','Tải JPG, PNG hoặc WebP (tối đa 10 MB). Nhấn để phóng to. Gỡ ảnh không thay đổi lịch sử.'],
 craneTemplateLanguages:['其他語言（英／西／越）','Other languages (EN / ES / VI)','Otros idiomas (EN / ES / VI)','Ngôn ngữ khác (EN / ES / VI)']
};for(const[k,v]of Object.entries(labels))translations[k]=Object.fromEntries(['zh','en','es','vi'].map((l,i)=>[l,v[i]]));
let dept='',equipment='',generation=0,context='',current=null,editor=null;
const allowed=()=>['admin','supervisor'].includes(profile?.role);
const oldRender=render;render=function(){if(view==='craneMonthlyManage'&&!allowed())view='board';oldRender();if(allowed()&&activeCountry){const b=document.createElement('button');b.className='nav'+(view==='craneMonthlyManage'?' active':'');b.dataset.view='craneMonthlyManage';b.innerHTML=txt('craneMonthlyManage');b.onclick=()=>{view='craneMonthlyManage';render();};const anchor=$('.side [data-view=cadreManage]');if(anchor)anchor.after(b);}};
const oldContent=renderContent;renderContent=function(){if(view==='craneMonthlyManage'&&allowed()&&activeCountry){renderManager();return;}generation++;oldContent();};
async function renderManager(){
 const key=activeCountry+':'+countryGeneration+':'+profile.account_id;if(context!==key){context=key;dept='';equipment='';current=null;}
 const departments=data.departments.filter(d=>d.is_active!==false&&accessDepartment(d.id,'crane_settings'));if(!departments.some(d=>d.id===dept))dept=departments.find(d=>d.id===profile.department_id)?.id||departments[0]?.id||'';
 const machines=data.equipment.filter(e=>e.department_id===dept&&!e.archived_at&&e.machine_no&&isCraneEquipment(e));if(!machines.some(e=>e.id===equipment))equipment=machines[0]?.id||'';
 $('.page-title h1').innerHTML=txt('craneMonthlyManage');$('#content').innerHTML=`<p class="notice">${txt('craneTemplateHelp')}</p><div class="filter-row"><label>${txt('department')}<select class="select" id="craneManageDept">${departments.map(d=>`<option value="${esc(d.id)}" ${d.id===dept?'selected':''}>${esc(nameOf(d))}</option>`).join('')}</select></label><label>${formHtml('f40_3')}<select class="select" id="craneManageEquipment">${machines.map(e=>`<option value="${esc(e.id)}" ${e.id===equipment?'selected':''}>${esc(e.machine_no)} · ${esc(nameOf(e))}</option>`).join('')}</select></label><button class="btn primary" id="craneTemplateEdit" disabled>${txt('craneTemplateEdit')}</button></div><p id="craneTemplateMessage" role="status"></p><div id="craneTemplatePreview"></div>`;
 $('#craneManageDept').onchange=e=>{dept=e.target.value;equipment='';renderManager();};$('#craneManageEquipment').onchange=e=>{equipment=e.target.value;renderManager();};$('#craneTemplateEdit').onclick=openEditor;
 if(!equipment){$('#craneTemplateMessage').textContent=formText('f40_9');return;}const ticket=++generation,target=equipment;
 try{const r=await api({action:'crane_template_get',equipment_id:target});if(ticket!==generation||view!=='craneMonthlyManage')return;current=r.template||{revision:0,items:structuredClone(CRANE_TEMPLATE.monthly.items)};$('#craneTemplateEdit').disabled=false;$('#craneTemplatePreview').innerHTML=current.items.map(it=>`<section class="item"><h3>${it.id}. ${formContentHtml(it.name)}</h3><p>${formContentHtml(it.standard)}</p>${cranePhotoMarkup(it,target)}</section>`).join('');bindCranePhotos($('#craneTemplatePreview'));}catch{if(ticket===generation)$('#craneTemplateMessage').textContent=t('error');}
}
function openEditor(){if(!current||editor)return;editor={equipment,context,revision:current.revision,items:structuredClone(current.items),busy:false,dirty:false};drawEditor();}
function drawEditor(){const s=editor;if(!s)return;const old=$('#craneTemplateEditor'),scroll=old?.querySelector('.dialog-body')?.scrollTop||0;old?.remove();
 const textField=(it,i,field,lang)=>`<label>${lang.toUpperCase()} · ${field==='name'?formHtml('f40_21'):txt('standard')}<textarea data-crane-index="${i}" data-field="${field}" data-language="${lang}" rows="${field==='name'?2:3}" maxlength="3000" ${lang==='zh'?'required':''}>${esc(it[field]?.[lang]||'')}</textarea></label>`;
 const m=document.createElement('div');m.className='modal open crane-modal';m.id='craneTemplateEditor';m.innerHTML=`<section class="dialog" role="dialog" aria-modal="true" aria-labelledby="craneTemplateTitle"><header class="dialog-head"><h2 id="craneTemplateTitle">${txt('craneTemplateEdit')}</h2><button class="x" type="button" id="craneTemplateClose">×</button></header><form id="craneTemplateForm"><div class="dialog-body"><p>${txt('craneTemplateHelp')}</p><p>${txt('craneTemplatePhotoHelp')}</p>${s.items.map((it,i)=>`<section class="item"><h3>${i+1}</h3>${['name','standard'].map(f=>textField(it,i,f,'zh')).join('')}<details><summary>${txt('craneTemplateLanguages')}</summary>${['en','es','vi'].map(l=>['name','standard'].map(f=>textField(it,i,f,l)).join('')).join('')}</details>${cranePhotoMarkup(it,s.equipment,'',true)}<label class="btn secondary">${txt('uploadReference')}<input type="file" accept="image/jpeg,image/png,image/webp" data-crane-upload="${i}"></label>${it.reference_photo_id?`<button type="button" class="btn secondary" data-crane-remove-photo="${i}">${txt('removeReference')}</button>`:''}</section>`).join('')}<button type="button" class="btn secondary" id="craneTemplateAdd" ${s.items.length>=200?'disabled':''}>${txt('craneTemplateAdd')}</button><p id="craneTemplateEditorMessage" role="alert"></p></div><footer class="dialog-foot"><button type="submit" class="btn primary" id="craneTemplateSave">${txt('craneTemplateSave')}</button></footer></form></section>`;document.body.append(m);m.querySelector('.dialog-body').scrollTop=scroll;
 const close=()=>{if(s.busy)return;if(s.dirty&&!confirm(formText('f40_51')))return;editor=null;m.remove();};$('#craneTemplateClose').onclick=close;m.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();close();}};
 m.querySelectorAll('[data-crane-index]').forEach(el=>el.oninput=()=>{s.items[+el.dataset.craneIndex][el.dataset.field][el.dataset.language]=el.value;s.dirty=true;});
 $('#craneTemplateAdd').onclick=()=>{if(s.items.length>=200)return;s.items.push({id:s.items.length+1,name:{zh:'',en:'',es:'',vi:''},standard:{zh:'',en:'',es:'',vi:''}});s.dirty=true;drawEditor();$('#craneTemplateAdd').scrollIntoView({block:'end'});};
 m.querySelectorAll('[data-crane-remove-photo]').forEach(b=>b.onclick=()=>{s.items[+b.dataset.craneRemovePhoto].reference_photo_id=null;s.dirty=true;drawEditor();});
 const disable=flag=>m.querySelectorAll('input,textarea,button').forEach(e=>e.disabled=flag);
 m.querySelectorAll('[data-crane-upload]').forEach(input=>input.onchange=async()=>{const file=input.files[0];if(!file||s.busy)return;s.busy=true;pendingReferenceUploads++;disable(true);$('#craneTemplateEditorMessage').textContent=t('photoUploading');try{const photo=await resizeReferencePhoto(file);const r=await api({action:'reference_photo_upload',photo,filename:file.name});if(editor!==s||!m.isConnected)return;s.items[+input.dataset.craneUpload].reference_photo_id=r.photo.id;s.dirty=true;}catch(e){if(m.isConnected)$('#craneTemplateEditorMessage').textContent=t(translations[e.message]?e.message:'error');s.busy=false;disable(false);return;}finally{pendingReferenceUploads--;s.busy=false;}if(editor===s&&m.isConnected)drawEditor();});
 $('#craneTemplateForm').onsubmit=async e=>{e.preventDefault();if(s.busy)return;if(s.items.some(it=>!it.name.zh.trim()||!it.standard.zh.trim())){$('#craneTemplateEditorMessage').textContent=t('craneTemplateRequired');return;}s.busy=true;disable(true);try{await api({action:'crane_template_save',equipment_id:s.equipment,revision:s.revision,items:s.items});editor=null;m.remove();if(view==='craneMonthlyManage')renderManager();}catch(e){if(m.isConnected)$('#craneTemplateEditorMessage').textContent=t(e.message==='record_changed'?'craneTemplateChanged':'error');}finally{s.busy=false;disable(false);}};
 bindCranePhotos(m);
}
const oldReset=resetCountry;resetCountry=function(){if(editor?.busy||countryBusy||pendingReferenceUploads)return;if(editor?.dirty&&!confirm(formText('f40_51')))return;editor=null;oldReset();};
const oldLogout=logout;logout=function(){editor=null;oldLogout();};
})();
